def get_top_customers(self, limit: int) -> list[dict[str, object]]:
    """Get top customers by lifetime value (non-cancelled orders only)."""
    customers_data = []
    for customer in self._customers.list_all():
        lifetime_value = 0
        for order in self._orders.list_for_customer(customer.customer_id):
            if order.status != "cancelled":
                summary = self.summarize(order)
                lifetime_value += summary.total_cents
        if lifetime_value > 0:
            customers_data.append({
                "customer_id": customer.customer_id,
                "name": customer.name,
                "lifetime_value_cents": lifetime_value,
            })
